// Decoder for the bundled Natural Earth coastline. GLOBE team. DESIGN 6.3.
//
// The payload is a base64 string in ./coastline-data.js, which is GENERATED by
// scripts/build-coastline.mjs and verified against a fresh generation by
// `node scripts/build-coastline.mjs --check`. Nothing here fetches anything: DESIGN 5 promises
// first paint before any network call, and a globe that has to download its own outline
// cannot keep that promise.
//
// Natural Earth is public domain and states that crediting is unnecessary. COASTLINE_ATTRIBUTION
// is shipped anyway. A product whose entire subject is provenance does not take an uncredited
// asset just because it is allowed to.
//
// Isomorphic: no node:* imports and no DOM. atob is available in browsers and in Node 22+.

import { COASTLINE_B64, COASTLINE_QUANT, COASTLINE_STATS, COASTLINE_ATTRIBUTION } from './coastline-data.js';

export { COASTLINE_STATS, COASTLINE_ATTRIBUTION, COASTLINE_QUANT };

/**
 * @typedef {Object} CoastlineGeometry
 * @property {Float64Array} lon Longitude in degrees, all lines concatenated.
 * @property {Float64Array} lat Latitude in degrees, same indexing as lon.
 * @property {Uint32Array} lineStart Index into lon and lat of the first point of each line.
 * @property {Uint32Array} lineCount Number of points in each line.
 */

/**
 * Base64 to bytes, without Buffer and without a dependency.
 * @param {string} b64
 * @returns {Uint8Array}
 */
export function base64ToBytes(b64) {
  if (typeof atob !== 'function') {
    throw new Error('base64ToBytes: no atob in this environment. Node 16 and later provide it '
      + 'globally, and every browser this page supports has had it for two decades.');
  }
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/**
 * Decode the zigzag varint delta stream.
 *
 * The cursor runs across lines, matching the encoder. A decoder that reset the cursor per line
 * would produce a map that looks almost right, which is the worst kind of wrong, so the
 * committed test decodes the real payload and asserts the extreme coordinates land where the
 * real world puts them rather than merely asserting it did not throw.
 *
 * @param {Uint8Array} bytes
 * @param {number} [quant]
 * @returns {CoastlineGeometry}
 */
export function decodeCoastline(bytes, quant = COASTLINE_QUANT) {
  let at = 0;

  const varint = () => {
    let result = 0;
    let shift = 0;
    for (;;) {
      if (at >= bytes.length) throw new RangeError('decodeCoastline: stream ended inside a varint');
      const b = bytes[at];
      at += 1;
      result |= (b & 0x7f) << shift;
      if ((b & 0x80) === 0) return result >>> 0;
      shift += 7;
      if (shift > 28) throw new RangeError('decodeCoastline: varint wider than 32 bits');
    }
  };
  const zag = (u) => (u >>> 1) ^ -(u & 1);

  const lineTotal = varint();
  const lineStart = new Uint32Array(lineTotal);
  const lineCount = new Uint32Array(lineTotal);

  // First pass is not possible without decoding, and decoding twice would double the cost on a
  // phone, so the point arrays grow into a plain array and narrow once at the end. The total
  // is a few thousand, not a few million.
  /** @type {number[]} */
  const lons = [];
  /** @type {number[]} */
  const lats = [];

  let curLon = 0;
  let curLat = 0;
  for (let i = 0; i < lineTotal; i++) {
    const n = varint();
    lineStart[i] = lons.length;
    lineCount[i] = n;
    for (let k = 0; k < n; k++) {
      curLon += zag(varint());
      curLat += zag(varint());
      lons.push(curLon / quant);
      lats.push(curLat / quant);
    }
  }
  if (at !== bytes.length) {
    throw new RangeError('decodeCoastline: ' + (bytes.length - at) + ' trailing bytes. The '
      + 'payload and the decoder disagree about the format, which means the shipped map is not '
      + 'the map the generator produced.');
  }

  return {
    lon: Float64Array.from(lons),
    lat: Float64Array.from(lats),
    lineStart,
    lineCount,
  };
}

/** @type {CoastlineGeometry|null} */
let cached = null;

/**
 * The bundled coastline, decoded once per page. DESIGN 6.5 stops the render loop when idle, so
 * this must not be redone per frame.
 * @returns {CoastlineGeometry}
 */
export function coastline() {
  if (cached === null) cached = decodeCoastline(base64ToBytes(COASTLINE_B64));
  return cached;
}

/** Test seam. Drops the memo so a test can decode twice and compare. */
export function resetCoastlineCache() {
  cached = null;
}
